package br.edu.scoa.academico.infraestrutura.documentos;
import br.edu.scoa.academico.aplicacao.documentos.ArmazenamentoDocumentos;import java.io.*;import java.nio.file.*;import java.util.*;
public final class ArmazenamentoLocalSeguro implements ArmazenamentoDocumentos {private static final long LIMITE=10L*1024*1024;private final Path raiz;public ArmazenamentoLocalSeguro(Path r){raiz=r.toAbsolutePath().normalize();if(raiz.toString().contains("\\src\\")||raiz.toString().contains("\\target\\"))throw new IllegalArgumentException("Diretório inseguro");}public String guardar(String n,String mime,long t,InputStream in)throws IOException{if(t<=0||t>LIMITE||!("application/pdf".equals(mime)||"image/png".equals(mime)||"image/jpeg".equals(mime)))throw new IllegalArgumentException("Arquivo inválido");Files.createDirectories(raiz);String k=UUID.randomUUID().toString();try(var o=Files.newOutputStream(raiz.resolve(k),StandardOpenOption.CREATE_NEW)){in.transferTo(o);}return k;}public void remover(String k)throws IOException{Files.deleteIfExists(raiz.resolve(k).normalize());}}
